   for(const [x,y,a,b,c,d,e,f,w] of roads){
    g.strokeStyle=color;g.lineWidth=w+extra;g.beginPath();g.moveTo(x,y);g.bezierCurveTo(a,b,c,d,e,f);g.stroke();
   }
